import hashlib
import json
from typing import Dict, List, Tuple, Any

class MerkleIntervalNode:
    def __init__(self, start_key: str, end_key: str, digest: str):
        self.start_key = start_key
        self.end_key = end_key
        self.digest = digest

class VectorClockEntropyEngine:
    @staticmethod
    data_hasher = lambda d: hashlib.sha256(json.dumps(d, sort_keys=True).encode("utf-8")).hexdigest()

    @classmethod
    def compute_digest(cls, items: Dict[str, Any]) -> str:
        if not items:
            return hashlib.sha256(b"").hexdigest()
        return cls.data_hasher(items)

    @classmethod
    def build_merkle_tree(cls, state_store: Dict[str, Any], bucket_size: int = 16) -> List[MerkleIntervalNode]:
        sorted_keys = sorted(state_store.keys())
        if not sorted_keys:
            return [MerkleIntervalNode("", "", cls.compute_digest({}))]
        nodes = []
        for i in range(0, len(sorted_keys), bucket_size):
            bucket_keys = sorted_keys[i:i + bucket_size]
            bucket_data = {k: state_store[k] for k in bucket_keys}
            digest = cls.compute_digest(bucket_data)
            nodes.append(MerkleIntervalNode(bucket_keys[0], bucket_keys[-1], digest))
        return nodes

    @staticmethod
    def compare_clocks(clock_a: Dict[str, int], clock_b: Dict[str, int]) -> str:
        keys = set(clock_a.keys()).union(set(clock_b.keys()))
        greater = False
        lesser = False
        for k in keys:
            va = clock_a.get(k, 0)
            vb = clock_b.get(k, 0)
            if va > vb:
                greater = True
            elif va < vb:
                lesser = True
        if greater and not lesser:
            return "after"
        if lesser and not greater:
            return "before"
        if not greater and not lesser:
            return "equal"
        return "concurrent"

    @classmethod
    def reconcile_state(cls, local_state: Dict[str, Any], local_clock: Dict[str, int], peer_state: Dict[str, Any], peer_clock: Dict[str, int]) -> Tuple[Dict[str, Any], Dict[str, int]]:
        relation = cls.compare_clocks(local_clock, peer_clock)
        if relation == "after":
            return local_state, local_clock
        if relation == "before":
            return peer_state, peer_clock
        merged_state = {**peer_state, **local_state}
        merged_clock = {k: max(local_clock.get(k, 0), peer_clock.get(k, 0)) for k in set(local_clock).union(peer_clock)}
        return merged_state, merged_clock

import time
import uuid
from typing import Dict, Any, Optional

class EntropyControlFrame:
    def __init__(self, sender_id: str, vector_clock: Dict[str, int], merkle_digest: str, message_id: Optional[str] = None, timestamp: Optional[float] = None):
        self.sender_id = sender_id
        self.vector_clock = vector_clock
        self.merkle_digest = merkle_digest
        self.message_id = message_id or str(uuid.uuid4())
        self.timestamp = timestamp or time.time()

    def to_dict(self) -> Dict[str, Any]:
        return {
            "sender_id": self.sender_id,
            "vector_clock": self.vector_clock,
            "merkle_digest": self.merkle_digest,
            "message_id": self.message_id,
            "timestamp": self.timestamp,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'EntropyControlFrame':
        return cls(
            sender_id=data["sender_id"],
            vector_clock=data["vector_clock"],
            merkle_digest=data["merkle_digest"],
            message_id=data.get("message_id"),
            timestamp=data.get("timestamp"),
        )

import unittest
from gossipmesh.p2p.entropy import VectorClockEntropyEngine, MerkleIntervalNode
from gossipmesh.p2p.protocol import EntropyControlFrame

class TestVectorClockEntropyEngine(unittest.TestCase):
    def test_compare_clocks(self):
        c1 = {"node_a": 2, "node_b": 1}
        c2 = {"node_a": 1, "node_b": 1}
        c3 = {"node_a": 2, "node_b": 2}
        c4 = {"node_a": 2, "node_c": 1}

        self.assertEqual(VectorClockEntropyEngine.compare_clocks(c1, c2), "after")
        self.assertEqual(VectorClockEntropyEngine.compare_clocks(c2, c1), "before")
        self.assertEqual(VectorClockEntropyEngine.compare_clocks(c1, c1), "equal")
        self.assertEqual(VectorClockEntropyEngine.compare_clocks(c1, c4), "concurrent")

    def test_merkle_tree_generation(self):
        store = {"key1": "val1", "key2": "val2", "key3": "val3"}
        nodes = VectorClockEntropyEngine.build_merkle_tree(store, bucket_size=2)
        self.assertGreaterEqual(len(nodes), 1)
        self.assertIsInstance(nodes[0], MerkleIntervalNode)

    def test_reconcile_state_concurrent(self):
        local_state = {"k1": "local_val"}
        local_clock = {"node_a": 2}
        peer_state = {"k2": "peer_val"}
        peer_clock = {"node_b": 2}

        merged_state, merged_clock = VectorClockEntropyEngine.reconcile_state(
            local_state, local_clock, peer_state, peer_clock
        )
        self.assertIn("k1", merged_state)
        self.assertIn("k2", merged_state)
        self.assertEqual(merged_clock["node_a"], 2)
        self.assertEqual(merged_clock["node_b"], 2)

    def test_protocol_frame(self):
        frame = EntropyControlFrame(sender_id="node_1", vector_clock={"node_1": 1}, merkle_digest="abc")
        d = frame.to_dict()
        frame2 = EntropyControlFrame.from_dict(d)
        self.assertEqual(frame.sender_id, frame2.sender_id)
        self.assertEqual(frame.merkle_digest, frame2.merkle_digest)

if __name__ == "__main__":
    unittest.main()
